const d = $input.first().json;
const profit = d.revenue - d.total_expenses;
const report = `Monthly Financial Summary\n${'='.repeat(40)}\n` +
  `Revenue: $${parseFloat(d.revenue).toLocaleString()} (${d.paid_count} invoices)\n` +
  `Expenses: $${parseFloat(d.total_expenses).toLocaleString()}\n` +
  `Net Profit: $${parseFloat(profit).toLocaleString()}\n` +
  `Overdue AR: $${parseFloat(d.overdue).toLocaleString()} (${d.overdue_count} invoices)\n` +
  `Profit Margin: ${(profit/d.revenue*100).toFixed(1)}%`;
return [{json:{report, profit}}];
